function parseArgs() {
  const out = {};
  for (const raw of process.argv.slice(2)) {
    const m = raw.match(/^--([^=]+)=(.*)$/);
    if (m) out[m[1]] = m[2];
  }
  return out;
}

const args = parseArgs();
const SUPABASE_URL = process.env.SUPABASE_URL;
const SERVICE_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY;
const LEVEL = args.level || 'pet';

function die(msg) { console.error(`❌ ${msg}`); process.exit(1); }

if (!SUPABASE_URL || !SERVICE_KEY) die('Thiếu biến môi trường SUPABASE_URL / SUPABASE_SERVICE_ROLE_KEY.');

async function sb(path, options = {}) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/${path}`, {
    ...options,
    headers: {
      apikey: SERVICE_KEY, Authorization: `Bearer ${SERVICE_KEY}`, 'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
  });
  if (!res.ok) throw new Error(`Supabase ${res.status}: ${(await res.text().catch(() => '')).slice(0, 300)}`);
  const text = await res.text();
  return text ? JSON.parse(text) : null;
}

// PostgREST mặc định chỉ trả tối đa 1000 dòng mỗi request (db-max-rows) — GET
// thường không báo lỗi gì cả, chỉ ÂM THẦM cắt bớt kết quả. Kho dùng chung đã
// vượt mốc 1000 dòng nên PHẢI phân trang (Range header) khi lấy toàn bộ
// title/prompt để dedup, nếu không các dòng ở cuối bảng sẽ "biến mất" khỏi
// danh sách đã có, khiến script tưởng chúng là bài MỚI và cố insert lại,
// gây lỗi 409 "duplicate key value violates unique constraint".
async function sbAll(path) {
  const PAGE = 1000;
  let all = [];
  let offset = 0;
  for (;;) {
    // eslint-disable-next-line no-await-in-loop
    const res = await fetch(`${SUPABASE_URL}/rest/v1/${path}`, {
      headers: {
        apikey: SERVICE_KEY, Authorization: `Bearer ${SERVICE_KEY}`, 'Content-Type': 'application/json',
        Range: `${offset}-${offset + PAGE - 1}`,
      },
    });
    if (!res.ok) throw new Error(`Supabase ${res.status}: ${(await res.text().catch(() => '')).slice(0, 300)}`);
    // eslint-disable-next-line no-await-in-loop
    const page = JSON.parse((await res.text()) || '[]');
    all = all.concat(page);
    if (page.length < PAGE) break;
    offset += PAGE;
  }
  return all;
}

async function main() {
  console.log(`Cấp độ: ${LEVEL} — ghi vào kho DÙNG CHUNG mọi gia đình (passage_pool/quiz_pool, xem migrate-18-content-pool.sql).`);

  // ----- Bài Luyện Dịch -----
  const existingTr = await sbAll(`passage_pool?select=title&level=eq.${LEVEL}`);
  const usedTitles = new Set(existingTr.map((r) => r.title));
  const newPassages = PASSAGES.filter((p) => !usedTitles.has(p.title));
  console.log(`\n📝 Luyện Dịch: ${existingTr.length} bài đã có trong kho, thêm ${newPassages.length} bài mới.`);
  const TR_BATCH = 50;
  for (let i = 0; i < newPassages.length; i += TR_BATCH) {
    const batch = newPassages.slice(i, i + TR_BATCH);
    // eslint-disable-next-line no-await-in-loop
    await sb('passage_pool', {
      method: 'POST',
      headers: { Prefer: 'return=minimal' },
      body: JSON.stringify(batch.map((p) => ({ level: LEVEL, ...p }))),
    });
    console.log(`  ✅ +${batch.length} bài (${i + 1}-${i + batch.length}/${newPassages.length})`);
  }

  // ----- Trắc Nghiệm Ngữ Pháp -----
  const existingGq = await sbAll(`quiz_pool?select=questions&level=eq.${LEVEL}&quiz_type=eq.grammar`);
  const existingPrompts = new Set(existingGq.flatMap((r) => (r.questions || []).map((q) => q.prompt)));
  const newQuizzes = GRAMMAR_QUIZZES.filter((qs) => !qs.some((q) => existingPrompts.has(q.prompt)));
  const totalExistingQ = existingGq.reduce((s, r) => s + (r.questions?.length || 0), 0);
  console.log(`\n🧩 Trắc Nghiệm: ${totalExistingQ} câu đã có trong kho, thêm ${newQuizzes.length * 5} câu mới (${newQuizzes.length} đề).`);
  for (const questions of newQuizzes) {
    // eslint-disable-next-line no-await-in-loop
    await sb('quiz_pool', {
      method: 'POST',
      headers: { Prefer: 'return=minimal' },
      body: JSON.stringify({ level: LEVEL, quiz_type: 'grammar', questions }),
    });
    console.log(`  ✅ 5 câu (${questions[0].structure.slice(0, 40)}...)`);
  }

  // ----- Ai Là Triệu Phú -----
  const existingMp = await sbAll(`quiz_pool?select=questions&level=eq.${LEVEL}&quiz_type=eq.millionaire`);
  const existingMpPrompts = new Set(existingMp.flatMap((r) => (r.questions || []).map((q) => q.prompt)));
  const newSets = MILLIONAIRE_SETS.filter((qs) => !qs.some((q) => existingMpPrompts.has(q.prompt)));
  const totalExistingMpQ = existingMp.reduce((s, r) => s + (r.questions?.length || 0), 0);
  console.log(`\n🏆 Ai Là Triệu Phú: ${existingMp.length} bộ (${totalExistingMpQ} câu) đã có trong kho, thêm ${newSets.length} bộ mới (${newSets.length * 15} câu).`);
  for (const questions of newSets) {
    if (questions.length !== 15) throw new Error(`1 bộ Ai Là Triệu Phú phải có ĐÚNG 15 câu, thấy ${questions.length} câu — kiểm tra lại MILLIONAIRE_SETS.`);
    // eslint-disable-next-line no-await-in-loop
    await sb('quiz_pool', {
      method: 'POST',
      headers: { Prefer: 'return=minimal' },
      body: JSON.stringify({ level: LEVEL, quiz_type: 'millionaire', questions }),
    });
    console.log(`  ✅ 15 câu (${questions[0].prompt.slice(0, 40)}...)`);
  }

  console.log('\n✅ Xong! Kho dùng chung đã cập nhật — MỌI gia đình (kể cả đăng ký sau này) sẽ tự động "mượn" nội dung này khi hết bài tái sử dụng trong nhà, thay vì luôn gọi AI (xem shared/api.js passagePoolPick/quizPoolPick, api/generate-daily-content.js sharedPassagePool/sharedQuizPool).');
}

main().catch((e) => die(e.message));
